using System.Collections;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GrimAwakeningEffect", menuName = "Data/Battle/Effects/Enemy/GrimAwakening Effect")]
public class GrimAwakeningEffect : Effect
{
	[Header("Doom")]
	[SerializeField]
	private int doomAmount;

	[SerializeField]
	private DefaultEffectAction doomAction;

	[SerializeField]
	private float delayToApplyDoom;

	[SerializeField]
	private float delayToApplyDoomWithVFX;

	[SerializeField]
	private float delayToSpawnVFX;

	[SerializeField]
	private float delayAfterDoomVFX;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedDescription = GetLocalizedDescription();
		string text = base.localizationManager.GetLocalizedEnemyEffectOwnerReceiveEffectFormatted(doomAction.Effect, doomAmount).RemoveLast().UppercaseFirst();
		if (LanguagesIndexes.IsCurrentLanguageRussian())
		{
			text = text.LowercaseFirst();
		}
		return Smart.Format(localizedDescription, text, amount);
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		int num = amount - 1;
		effectOwner.GetComponent<UnitEffects>().IsEffectActiveAndDecreaseEffect(this, 1, activateFeedback: true, removeOnZero: false);
		if (num == 0)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ApplyEmpower(effectOwner, doomAmount));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		return amount;
	}

	private IEnumerator ApplyEmpower(GameObject effectOwner, int amount)
	{
		float seconds = (IsVFXEnabled() ? delayToSpawnVFX : 0f);
		yield return new WaitForSeconds(seconds);
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		component.IsEffectActive(this);
		component.IsEffectActiveRemoveEffect(this, activateFeedback: false);
		SpawnVFX(GetVFXOwnerPosition(effectOwner), 4f);
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
		}
		float seconds2 = (IsVFXEnabled() ? delayToApplyDoomWithVFX : delayToApplyDoom);
		yield return new WaitForSeconds(seconds2);
		doomAction.CastTargetAmount(effectOwner, amount, null);
		if (IsVFXEnabled())
		{
			_ = delayAfterDoomVFX;
		}
		yield return new WaitForSeconds(delayAfterDoomVFX);
	}
}
